```go
package main

import "fmt"

func count(limit int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for n := 1; n <= limit; n++ { out <- n }
    }()
    return out
}

func main() {
    total := 0
    for n := range count(3) { total += n }
    fmt.Println(total)
}
```
The producer owns the output and closes after sending `1`, `2`, and `3`. Range drains them and the output is `6`.

```go
package main

import (
    "context"
    "fmt"
)

func squares(ctx context.Context, input <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for n := range input {
            select {
            case out <- n * n:
            case <-ctx.Done():
                return
            }
        }
    }()
    return out
}

func main() {
    input := make(chan int, 2)
    input <- 2
    input <- 3
    close(input)

    ctx, cancel := context.WithCancel(context.Background())
    out := squares(ctx, input)
    fmt.Println(<-out)
    cancel()
    for range out {}
    fmt.Println("stopped")
}
```
The first output is `4`; cancellation then lets the stage return instead of leaving a blocked sender, and `stopped` is printed.
